float sdCircle( vec2 p, float r )
{ return length(p) - r;}


vec3 cirgira(float pradio, vec2 uv , vec2 ppos,vec3 colout, vec3 colin,float pt, float tmas)
{
vec2 pos=ppos;

vec3 color = vec3(0.0); // Fondo negro
color=colout;

    // Parámetros
    float ringRadius = pradio; //0.3;  // Radio del anillo
    float circleRadius = 0.015*2.5; // Radio de los círculos
    int circleCount = 10;      // Cantidad de círculos
    float rotationSpeed = 0.25; // Velocidad de rotación

    // Ángulo de rotación basado en el tiempo
    float angleOffset = -(pt+tmas) * rotationSpeed;

    for (int i = 0; i < circleCount; i++) {
        // Calcular la posición del círculo en el anillo
        float angle = angleOffset + float(i) * (6.283185 / float(circleCount)); // 2*PI dividido por la cantidad
        vec2 circlePos = pos+vec2(cos(angle), sin(angle)) * ringRadius;

        // Dibujar el círculo
        float dist = length(uv - circlePos);
        if (dist < circleRadius) {
            //color += smoothstep(circleRadius, circleRadius - 0.01, dist) * vec3(0.2, 0.6, 1.0);
            color += smoothstep(circleRadius, circleRadius - 0.01, dist) * colin;
        }
    }

    return color;

}

